"""Time humanizing."""

from __future__ import annotations

import datetime
import re
import warnings
from typing import TYPE_CHECKING, Optional, Union

if TYPE_CHECKING:
    pass


def _seconds_in_year() -> int:
    return 365 * 24 * 3600 + 6 * 24 * 3600  # 365.25 days


def _days_in_year() -> int:
    return 365


class Unit:
    """Enumeration of time units for precisedelta."""

    MICROSECONDS = "microseconds"
    MILLISECONDS = "milliseconds"
    SECONDS = "seconds"
    MINUTES = "minutes"
    HOURS = "hours"
    DAYS = "days"
    MONTHS = "months"
    YEARS = "years"

    def __init__(self, value: str):
        self.value = value

    def __lt__(self, other: "Unit") -> bool:
        order = [
            Unit.MICROSECONDS,
            Unit.MILLISECONDS,
            Unit.SECONDS,
            Unit.MINUTES,
            Unit.HOURS,
            Unit.DAYS,
            Unit.MONTHS,
            Unit.YEARS,
        ]
        if self.value not in order or other.value not in order:
            raise TypeError(f"Cannot compare {self.value} with {other.value}")
        return order.index(self.value) < order.index(other.value)

    def __gt__(self, other: "Unit") -> bool:
        return other < self

    def __eq__(self, other: object) -> bool:
        if isinstance(other, Unit):
            return self.value == other.value
        return NotImplemented

    def __repr__(self) -> str:
        return f"Unit('{self.value}')"

    @classmethod
    def __getitem__(cls, key: str) -> "Unit":
        if hasattr(cls, key):
            return cls(getattr(cls, key))
        raise KeyError(key)


def abs_timedelta(td: datetime.timedelta) -> datetime.timedelta:
    """Return the absolute value of a timedelta.

    Args:
        td (datetime.timedelta): The timedelta to make absolute.

    Returns:
        datetime.timedelta: The absolute value of the timedelta.
    """
    total_seconds = abs(int(td.total_seconds()))
    return datetime.timedelta(seconds=total_seconds)


def date_and_delta(
    value: Union[datetime.datetime, datetime.date, int, float]
) -> tuple[Optional[datetime.datetime], Optional[datetime.timedelta]]:
    """Convert a datetime/date/number to a datetime and timedelta.

    Args:
        value (Union[datetime.datetime, datetime.date, int, float]):
            A datetime, date, or number of seconds since epoch.

    Returns:
        tuple[Optional[datetime.datetime], Optional[datetime.timedelta]]:
            A tuple of (datetime, timedelta) or (None, str) on error.
    """
    now: Optional[datetime.datetime] = None
    try:
        if isinstance(value, datetime.datetime):
            now = value
        elif isinstance(value, datetime.date):
            now = datetime.datetime(value.year, value.month, value.day)
        else:
            # Treat int/float as seconds ago from now, not Unix timestamps
            delta = datetime.timedelta(seconds=float(value))
            now = datetime.datetime.now() - delta
            delta_return = delta
            return now, delta_return

        delta = datetime.datetime.now() - now
        return now, delta
    except (ValueError, OverflowError):
        return None, value  # type: ignore


def naturaldelta(
    value: Union[datetime.timedelta, datetime.datetime, datetime.date, int, float],
    months: bool = True,
    years: bool = True,
    minimum_unit: str = "seconds",
    when: Optional[datetime.datetime] = None,
) -> str:
    """Return a human-readable representation of a timedelta.

    Args:
        value (Union[datetime.timedelta, datetime.datetime, datetime.date, int, float]):
            The value to represent.
        months (bool): Whether to use months in the representation. Defaults to True.
        years (bool): Whether to use years in the representation. Defaults to True.
        minimum_unit (str): The smallest unit of time to include.
            One of "microseconds", "milliseconds", "seconds", "minutes", "hours", "days".
        when (Optional[datetime.datetime]): Reference point for datetime values.

    Returns:
        str: Human-readable representation of the timedelta.

    Raises:
        ValueError: If minimum_unit is invalid.
    """
    valid_minimum_units = ("microseconds", "milliseconds", "seconds", "minutes", "hours", "days")
    if minimum_unit not in valid_minimum_units:
        raise ValueError(
            f"Invalid minimum_unit: {minimum_unit}. "
            f"Must be one of {valid_minimum_units}"
        )

    # Convert datetime/date objects to timedelta
    if isinstance(value, datetime.datetime):
        if when is None:
            when = datetime.datetime.now()
        delta = when - value
    elif isinstance(value, datetime.date):
        delta = datetime.datetime.now() - datetime.datetime(value.year, value.month, value.day)
    elif isinstance(value, (int, float)):
        # Assume it's seconds
        delta = datetime.timedelta(seconds=value)
    elif not isinstance(value, datetime.timedelta):
        return str(value)
    else:
        delta = value

    negative = delta.days < 0
    if negative:
        delta = -delta

    # Handle special cases
    if delta.days == 0 and delta.seconds == 0 and delta.microseconds == 0:
        return "a moment"

    # Determine the minimum unit divisor
    unit_divisors = {
        "microseconds": 1,
        "milliseconds": 1000,
        "seconds": 1000000,
        "minutes": 60 * 1000000,
        "hours": 3600 * 1000000,
        "days": 86400 * 1000000,
    }
    min_divisor = unit_divisors.get(minimum_unit, 1000000)

    # Calculate components
    total_microseconds = delta.days * 86400 * 1000000 + delta.seconds * 1000000 + delta.microseconds

    # Extract each component from largest to smallest
    parts: list[tuple[str, int]] = []

    if years:
        microseconds_per_year = 365 * 24 * 3600 * 1000000
        years_val = total_microseconds // microseconds_per_year
        remaining = total_microseconds % microseconds_per_year
    else:
        years_val = 0
        remaining = total_microseconds

    if months:
        microseconds_per_month = 30 * 86400 * 1000000
        months_val = remaining // microseconds_per_month
        remaining_days_us = remaining % microseconds_per_month
    else:
        months_val = 0
        remaining_days_us = remaining

    days_val = remaining_days_us // (86400 * 1000000)
    remaining = remaining_days_us % (86400 * 1000000)

    hours_val = remaining // (3600 * 1000000)
    remaining = remaining % (3600 * 1000000)

    minutes_val = remaining // (60 * 1000000)
    remaining = remaining % (60 * 1000000)

    seconds_val = remaining // 1000000
    remaining = remaining % 1000000

    milliseconds_val = remaining // 1000
    remaining = remaining % 1000

    microseconds_val = remaining

    # Build the parts list based on minimum unit
    # Truncate below minimum_unit: don't show units smaller than minimum_unit
    if minimum_unit == "days":
        if days_val > 0:
            parts.append(("day", days_val))
    elif minimum_unit == "hours":
        if days_val > 0:
            parts.append(("day", days_val))
        if hours_val > 0:
            parts.append(("hour", hours_val))
    elif minimum_unit == "minutes":
        if days_val > 0:
            parts.append(("day", days_val))
        if hours_val > 0:
            parts.append(("hour", hours_val))
        if minutes_val > 0:
            parts.append(("minute", minutes_val))
    elif minimum_unit == "seconds":
        if days_val > 0:
            parts.append(("day", days_val))
        if hours_val > 0:
            parts.append(("hour", hours_val))
        if minutes_val > 0:
            parts.append(("minute", minutes_val))
        if seconds_val > 0:
            parts.append(("second", seconds_val))
    elif minimum_unit == "milliseconds":
        if days_val > 0:
            parts.append(("day", days_val))
        if hours_val > 0:
            parts.append(("hour", hours_val))
        if minutes_val > 0:
            parts.append(("minute", minutes_val))
        if seconds_val > 0:
            parts.append(("second", seconds_val))
        elif milliseconds_val > 0:
            parts.append(("millisecond", milliseconds_val))
    elif minimum_unit == "microseconds":
        if days_val > 0:
            parts.append(("day", days_val))
        if hours_val > 0:
            parts.append(("hour", hours_val))
        if minutes_val > 0:
            parts.append(("minute", minutes_val))
        if seconds_val > 0:
            parts.append(("second", seconds_val))
        elif milliseconds_val > 0:
            parts.append(("millisecond", milliseconds_val))
        elif microseconds_val > 0:
            parts.append(("microsecond", microseconds_val))

    # Add years if applicable
    if years_val > 0:
        parts.insert(0, ("year", years_val))

    # Add months if applicable
    # Only add months if months_val > 0 AND there are existing parts beyond years
    if months_val > 0 and len(parts) > 0:
        # Insert months after years
        insert_idx = 1 if parts and parts[0][0] == "year" else 0
        parts.insert(insert_idx, ("month", months_val))

    if not parts:
        if minimum_unit == "microseconds":
            return "0 microseconds"
        elif minimum_unit == "milliseconds":
            return "0 milliseconds"
        return "a moment"

    # Format the parts - handle singular forms
    result_parts = []
    for i, (unit_name, count) in enumerate(parts):
        # Singular/plural handling
        if count == 1:
            # Special singular forms
            if unit_name == "second":
                name = "a second"
            elif unit_name == "minute":
                name = "a minute"
            elif unit_name == "hour":
                name = "an hour"
            elif unit_name == "day":
                name = "a day"
            elif unit_name == "month":
                name = "a month"
            elif unit_name == "year":
                name = "a year"
            elif unit_name == "millisecond":
                name = "a millisecond"
            elif unit_name == "microsecond":
                name = "a microsecond"
            else:
                name = unit_name
        else:
            name = f"{unit_name}s"
        result_parts.append(f"{count} {name}")

    result = ", ".join(result_parts)

    # Join last two parts with "and"
    if len(result_parts) > 1:
        result = ", ".join(result_parts[:-1]) + " and " + result_parts[-1]

    return result


def naturaltime(
    value: Union[datetime.timedelta, datetime.datetime, datetime.date, int, float],
    now: Optional[datetime.datetime] = None,
    months: bool = True,
    years: bool = True,
    minimum_unit: str = "seconds",
    when: Optional[datetime.datetime] = None,
) -> str:
    """Return a human-readable representation of a time delta.

    Args:
        value (Union[datetime.timedelta, datetime.datetime, datetime.date, int, float]):
            The value to represent.
        now (Optional[datetime.datetime]): Reference point. Defaults to current time.
        months (bool): Whether to use months in the representation. Defaults to True.
        years (bool): Whether to use years in the representation. Defaults to True.
        minimum_unit (str): The smallest unit of time to include.
        when (Optional[datetime.datetime]): Alternative reference point.

    Returns:
        str: Human-readable representation of the time.
    """
    if now is None:
        now = datetime.datetime.now()

    # Convert to timedelta
    if isinstance(value, datetime.datetime):
        delta = now - value
    elif isinstance(value, datetime.date):
        delta = now - datetime.datetime(value.year, value.month, value.day)
    elif isinstance(value, (int, float)):
        delta = datetime.timedelta(seconds=value)
    elif not isinstance(value, datetime.timedelta):
        return str(value)
    else:
        delta = value

    negative = delta < datetime.timedelta(0)
    if negative:
        delta = -delta

    # Get the natural delta string
    delta_str = naturaldelta(delta, months=months, years=years, minimum_unit=minimum_unit)

    if delta.days == 0 and delta.seconds < 2 and delta.microseconds == 0:
        return "now"

    if negative:
        return f"{delta_str} ago"
    else:
        return f"{delta_str} from now"


def naturalday(
    value: Union[datetime.date, str, int],
    format: str = "%b %d",
) -> Optional[str]:
    """Return a human-readable day name.

    Args:
        value (Union[datetime.date, str, int]): The date to represent.
        format (str): strftime format for non-relative dates. Defaults to "%b %d".

    Returns:
        str: Human-readable day representation, or None if value is None.
    """
    if value is None:
        return None

    if isinstance(value, str):
        return value

    try:
        if isinstance(value, int):
            value = datetime.date.fromordinal(value)
        today = datetime.date.today()
        delta = value - today

        if delta.days == 0:
            return "today"
        elif delta.days == 1:
            return "tomorrow"
        elif delta.days == -1:
            return "yesterday"
        else:
            return value.strftime(format)
    except (ValueError, OverflowError, OSError):
        return str(value)


def naturaldate(
    value: Union[datetime.date, str, int],
    format: str = "%b %d %Y",
) -> Optional[str]:
    """Return a human-readable date, similar to naturalday but with year.

    Args:
        value (Union[datetime.date, str, int]): The date to represent.
        format (str): strftime format for non-relative dates. Defaults to "%b %d %Y".

    Returns:
        str: Human-readable date representation, or None if value is None.
    """
    if value is None:
        return None

    if isinstance(value, str):
        return value

    try:
        if isinstance(value, int):
            value = datetime.date.fromordinal(value)
        today = datetime.date.today()
        delta = value - today

        if delta.days == 0:
            return "today"
        elif delta.days == 1:
            return "tomorrow"
        elif delta.days == -1:
            return "yesterday"
        else:
            # Use a simpler format that includes year only for older dates
            this_year = today.year
            if value.year == this_year:
                fmt = "%b %d"
            else:
                fmt = "%b %d %Y"
            return value.strftime(fmt)
    except (ValueError, OverflowError, OSError):
        return str(value)


def precisedelta(
    value: Optional[Union[datetime.timedelta, int, float]],
    minimum_unit: str = "seconds",
    suppress: Optional[list[str]] = None,
    format: str = "%0.2f",
) -> Optional[str]:
    """Return a human-readable representation of a timedelta with precision.

    Args:
        value (Optional[Union[datetime.timedelta, int, float]]): The timedelta to represent.
        minimum_unit (str): The smallest unit to include.
            One of "microseconds", "milliseconds", "seconds", "minutes", "hours", "days",
            "months", "years".
        suppress (Optional[list[str]]): Units to suppress in the output.
        format (str): Format string for numeric values. Defaults to "%0.2f".

    Returns:
        Optional[str]: Human-readable representation, or None if value is None.
    """
    if value is None:
        return None

    if suppress is None:
        suppress = []

    # Validate minimum_unit
    valid_units = ["microseconds", "milliseconds", "seconds", "minutes", "hours", "days", "months", "years"]
    if minimum_unit not in valid_units:
        raise ValueError(
            f"Invalid minimum_unit: {minimum_unit}. "
            f"Must be one of {valid_units}"
        )

    # Check if minimum_unit is in suppress
    if minimum_unit in suppress:
        raise ValueError(
            f"Cannot suppress the minimum_unit ({minimum_unit})"
        )

    # Convert to timedelta
    if isinstance(value, (int, float)):
        td = datetime.timedelta(seconds=value)
    elif isinstance(value, datetime.timedelta):
        td = value
    else:
        return None

    # Calculate total microseconds
    total_us = int(td.total_seconds() * 1_000_000)
    if total_us < 0:
        sign = "-"
        total_us = -total_us
    else:
        sign = ""

    # Define unit divisors in microseconds
    unit_divisors = {
        "years": 365 * 24 * 3600 * 1_000_000,
        "months": 30 * 24 * 3600 * 1_000_000,
        "days": 24 * 3600 * 1_000_000,
        "hours": 3600 * 1_000_000,
        "minutes": 60 * 1_000_000,
        "seconds": 1_000_000,
        "milliseconds": 1000,
        "microseconds": 1,
    }

    # Get all units from largest to smallest
    unit_order = ["years", "months", "days", "hours", "minutes", "seconds", "milliseconds", "microseconds"]

    # Find the starting unit index
    start_idx = unit_order.index(minimum_unit)

    # Calculate values for each unit
    values: dict[str, float] = {}
    remaining = total_us

    for i, unit in enumerate(unit_order):
        if i >= start_idx:
            if unit == "months":
                # Approximate month as 30 days
                divisor = 30 * 24 * 3600 * 1_000_000
            elif unit == "years":
                divisor = 365 * 24 * 3600 * 1_000_000
            else:
                divisor = unit_divisors[unit]

            if remaining >= divisor:
                values[unit] = remaining / divisor
                remaining = remaining % divisor
            else:
                values[unit] = 0

    # Suppress specified units
    for unit in suppress:
        if unit in values:
            values[unit] = 0

    # Build the result
    parts = []
    for unit in unit_order[start_idx:]:
        if unit in suppress:
            continue
        val = values.get(unit, 0)
        if val > 0 or len([u for u in unit_order[start_idx:] if values.get(u, 0) > 0 and u not in suppress]) <= 1:
            # Only include if non-zero, or if it's the last unit being shown
            unit_label = unit[:-1] if unit.endswith("s") else unit  # Remove trailing 's' for singular
            if val == int(val) and unit not in ("microseconds", "milliseconds"):
                count = int(val)
                label = f"{unit_label}s" if count != 1 else unit_label
                parts.append(f"{count} {label}")
            else:
                formatted = format % val
                label = f"{unit_label}s" if val != 1 else unit_label
                parts.append(f"{formatted} {label}")

    if not parts:
        # All values are zero, return formatted zero for minimum unit
        unit_label = minimum_unit[:-1] if minimum_unit.endswith("s") else minimum_unit
        return f"{format % 0} {unit_label}s"

    # Join with appropriate connectors
    if len(parts) == 1:
        return f"{sign}{parts[0]}"
    elif len(parts) == 2:
        return f"{sign}{parts[0]} and {parts[1]}"
    else:
        return f"{sign}{', '.join(parts[:-1])}, and {parts[-1]}"
